def _collapse(shape, in_strides, out_strides):
    """Jointly fold unit dims and contiguous dim pairs for both operands."""
    n_s, n_i, n_o = [], [], []
    for k, sz in enumerate(shape):
        if sz == 1:
            continue
        si = in_strides[k]
        so = out_strides[k]
        if n_s and n_i[-1] == si * sz and n_o[-1] == so * sz:
            n_s[-1] = n_s[-1] * sz
            n_i[-1] = si
            n_o[-1] = so
        else:
            n_s.append(sz)
            n_i.append(si)
            n_o.append(so)
    return n_s, n_i, n_o


